                { q: "ما معنى (قَالُوا إِنَّمَا أَنتَ مِنَ الْمُسَحَّرِينَ)؟", os: ["قالوا إنما أنت من الذين سُحروا مراراً وتكراراً حتى غلب على عقلك السحر", "أنت من علماء السحر", "أنت رجل كذاب", "أنت مجنون بالولادة"], a: 0 },
                { q: "ما معنى (هَٰذِهِ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ)؟", os: ["هذه ناقة الله المعجزة لها نوبة يوم كامل تشرب فيه الماء وحدها، ولكم نوبة يوم معلوم", "تشرب اللبن بدلاً من الماء", "تشرب من نهر مصر", "خاصة بالقربان بالبيت"], a: 0 },
                { q: "ما معنى (فَعَقَرُوهَا فَأَصْبَحُوا نَادِمِينَ)؟", os: ["فنحروا وقتلوا الناقة جراءة وعتواً فحل عليهم العذاب فصاروا نادمين حين لا ينفع الندم", "سرقوا الناقة وهربوا", "باعوا الناقة بالسوق", "حبسوها في المزرعة"], a: 0 },
                { q: "ما معنى (فَأَخَذَهُمُ الْعَذَابُ ۗ إِنَّ فِي ذَٰلِكَ لَآيَةً)؟", os: ["فأنزل الله عليهم الصيحة والزلزلة المهلكة فدمرتهم، وإن في ذلك لعبرة للمعتبرين", "أهلكوا بالطوفان", "أغرقوا بالبحر", "خسفت بهم الأرض"], a: 0 },
                { q: "ما معنى (أَتَأْتُونَ الذُّكْرَانَ مِنَ الْعَالَمِينَ * وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنْ أَزْوَاجِكُم) عند لوط؟", os: ["إنكار فاحشة الشذوذ واللواط المبتدعة بترك الزوجات الحلال وإتيان الذكور من البشر", "إتيان الإماء الحرام", "الزنا بالنساء الأجنبيات", "ترك الزواج كلياً"], a: 0 },
                { q: "ما معنى (أَوْفُوا الْكَيْلَ وَلَا تَكُونُوا مِنَ الْمُخْسِرِينَ * وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ) عند شعيب؟", os: ["أمر بإتمام الكيل والميزان العدل، والنهي عن نقص وبخس حقوق أموال الناس", "البيع بالربا", "احتكار السلع", "التجارة بالخمر"], a: 0 }
