                { q: "ما معنى (فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا) في دعوة نوح؟", os: ["مكث نوح عليه السلام يدعو قومه للتوحيد تسعمائة وخمسين سنة صابراً محتسباً", "عاش ألفين وخمسين سنة", "لبث بالسفينة 950 يوماً", "عاش 50 سنة فقط"], a: 0 },
                { q: "ما معنى (فَأَنجَيْنَاهُ وَأَصْحَابَ السَّفِينَةِ وَجَعَلْنَاهَا آيَةً لِّلْعَالَمِينَ)؟", os: ["سلمنا نوحاً ومن ركب معه بالمركب المبارك، وجعلنا حادثة السفينة والنصر عبرة وعلامة للخلق", "جعلنا القصر آية", "جعلنا البحر مالحاً", "خاص بأهل بابل"], a: 0 },
                { q: "ما معنى (فَابْتَغُوا عِندَ اللَّهِ الرِّزْقَ وَاعْبُدُوهُ وَاشْكُرُوا لَهُ) ب إبراهيم والعنكبوت؟", os: ["اطلبوا الرزق والنعمة من الله وحده لا من الأصنام العاجزة، واعبدوه واشكروا أفضاله", "اطلبوا المال بالتجارة فقط", "اشكروا الملوك", "خاص بأهل مكة"], a: 0 },
                { q: "ما معنى (وَإِن تَكُونُوا كَبُرَتْ عَلَيْكُمْ... فَمَا جَوَابُ قَوْمِهِ إِلَّا أَن قَالُوا اقْتُلُوهُ أَوْ حَرِّقُوهُ)؟", os: ["عجز وعناد قوم إبراهيم ب ترك الحجة العقلية واللجوء للبطش بالقتل أو الإحراق بالنار", "سجنوا إبراهيم بالحديد", "طردوه من البلاد", "صالحوه على المال"], a: 0 },
                { q: "ما معنى (إِنَّمَا اتَّخَذْتُم مِّن دُونِ اللَّهِ أَوْثَانًا مَّوَدَّةَ بَيْنِكُمْ فِي الْحَيَاةِ الدُّنْيَا)؟", os: ["عبادتكم للأصنام إنما كانت لاجتماعكم ومودتكم الجاهلية المنسوبة للآباء بالدنيا وتزول بالآخرة", "اتخذتموها تجارة بالأسواق", "صنعتموها من الذهب", "خاصة بأهل الروم"], a: 0 },
                { q: "ما معنى (اتْلُ مَا أُوحِيَ إِلَيْكَ مِنَ الْكِتَابِ وَأَقِمِ الصَّلَاةَ) ختام الجزء 20؟", os: ["اقرأ وداوم على تدبر القرآن وأقم الصلاة بحدودها وإخلاصها لأنها الصارف الأعظم عن المعاصي", "اقرأ التوراة والإنجيل", "صل صلاة العيدين فقط", "خاص بالنبي وحده"], a: 0 }
