                { q: "ما معنى (أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ اللَّهُ) في دفاع مؤمن آل فرعون؟", os: ["استنكار وإنكار شجاع على فرعون وقومه كيف يقتلون موسى لمجرد إعلانه توحيد الله وإتيانه بالبينات", "استنكار على قتل القبطي", "دفاع عن هارون", "خاص بأهل بابل"], a: 0 },
                { q: "ما معنى (وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ ۚ إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ)؟", os: ["أسلم وألجئ وأتوكل وأعتمد في أمري وحمايتي على الله وحده، وهو العالم المطلع بأحوال عباده", "أفوض أمري للقاضي", "أترك العمل والسعي", "خاص بالقتال بالسيف"], a: 0 },
                { q: "ما معنى (النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا) لآل فرعون؟", os: ["دليل صريح على عذاب البرزخ والقبر لفرعون وقومه برؤية وتأثر بمكانهم في النار صباحاً ومساءً إلى القيامة", "عرض النار عليهم بالدنيا", "عذابهم بالليل والنهار في الجحيم فقط", "خاص بأهل الجاهلية"], a: 0 },
                { q: "ما معنى (إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا) بسورة فصلت؟", os: ["الذين أخلصوا التوحيد لله وحده، ثم ثبتوا واستقاموا على الطاعة والشرع بلا روغان ولا معاصٍ", "قالوا كلمتهم باللسان فقط", "استقاموا في التجارة والبيع", "خاص بالصحابة ببدر"], a: 0 },
                { q: "ما معنى (مَّنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ ۖ وَمَنْ أَسَاءَ فَعَلَيْهَا) ختام الجزء 24؟", os: ["قاعدة وعدل إلهي بأن نفع وثواب العمل الصالح عائد على العبد نفسه، ووزر وشؤم الإساءة واقع عليه وحده", "العمل الصالح ينفع الأقارب فقط", "الإساءة يتحملها الشياطين", "خاص بأهل الكتاب"], a: 0 }
