                { q: "ما هي الكلمة الوحيدة الدقيقة التي ختمت بها الآية رقم 15 في سورة الشورى (فَلِذَٰلِكَ فَادْعُ ۖ وَاسْتَقِمْ كَمَا أُمِرْتَ...)؟", os: ["اللَّهُ رَبُّنَا وَرَبُّكُمْ ۖ لَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ... وَإِلَيْهِ الْمَصِيرُ", "وكان الله بكل شيء عليماً", "إن الله سريع الحساب", "وهو العزيز الحكيم"], a: 0 },
                { q: "ما هو ختام الآية رقم 38 في سورة الدخان (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا...)؟", os: ["لَاعِبِينَ * مَا خَلَقْنَاهُمَا إِلَّا بِالْحَقِّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", "باطلاً ذلك ظن الذين كفروا", "عبثاً وأنكم إلينا لا ترجعون", "إلا ليعبدون"], a: 0 },
                { q: "كم مرة ورد لفظ (مُّبِينٍ) أو (الْمُبِينِ) في فواتح السور بالحواميم في هذا الجزء؟", os: ["تكرر في افتتاح الزخرف والدخان (وَالْكِتَابِ الْمُبِينِ) وفصلت والجاثية", "مرة واحدة فقط", "5 مرات", "لا يوجد بالحواميم"], a: 0 },
                { q: "ما الجملة الاعتراضية الدقيقة في الآية 51 من سورة الشورى عند بيان طرق الوحي؟", os: ["وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ اللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَاءِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ مَا يَشَاءُ ۚ إِنَّهُ عَلِيٌّ حَكِيمٌ", "وكذلك أوحينا إليك روحاً من أمرنا", "ما كنت تدري ما الكتاب", "ولكن جعلناه نورا"], a: 0 },
                { q: "ما الفارق بين قوله (وَإِنَّهُ فِي أُمِّ الْكِتَابِ لَدَيْنَا لَعَلِيٌّ حَكِيمٌ) بالزخرف 4 وقوله بالبروج؟", os: ["في الزخرف أثبت مكانة القرآن باللوح المحفوظ بـ (لَدَيْنَا لَعَلِيٌّ حَكِيمٌ)، وفي البروج (بَلْ هُوَ قُرْآنٌ مَّجِيدٌ * فِي لَوْحٍ مَّحْفُوظٍ)", "لا يوجد فارق", "في البروج ذكر علي حكيم", "في الزخرف ذكر لوح محفوظ"], a: 0 },
                { q: "ما هو ختام الآية رقم 77 في سورة الزخرف (وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ...)؟", os: ["قَالَ إِنَّكُم مَّاكِثُونَ * لَقَدْ جِئْنَاكُم بِالْحَقِّ وَلَٰكِنَّ أَكْثَرُكُمْ لِلْحَقِّ كَارِهُونَ", "فذوقوا العذاب بما كنتم تكفرون", "قال اخسئوا فيها ولا تكلمون", "فلا كاشف له إلا هو"], a: 0 },
                { q: "ما الكلمة التي بدأت بها الآية 18 في سورة الجاثية في إتيان الشريعة؟", os: ["ثُمَّ جَعَلْنَاكَ عَلَىٰ شَرِيعَةٍ مِّنَ الْأَمْرِ فَاتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لَا يَعْلَمُونَ", "ولقد آتينا بني إسرائيل الكتاب", "إنهم لن يغنوا عنك من الله شيئاً", "هذا بصائر للناس"], a: 0 },
                { q: "ما هي الآية رقم 24 من سورة الجاثية في مقالة الدهريين بإنكار البعث؟", os: ["وَقَالُوا مَا هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَا إِلَّا الدَّهْرُ ۚ وَمَا لَهُم بِذَٰلِك مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَظُنُّونَ", "قل الله يحييكم ثم يميتكم", "وإذا تتلى عليهم آياتنا بينات", "قل سيروا في الأرض"], a: 0 },
                { q: "ما اللفظ الدقيق الوارد في خردل الشرك والنار بآية الجاثية 26 (قُلِ اللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ...)؟", os: ["ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ الْقِيَامَةِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ", "وله ملك السماوات والأرض", "ويوم تقوم الساعة يومئذ يخسر المبطلون", "وترى كل أمة جاثية"], a: 0 },
                { q: "ما هو ختام الآية رقم 36 في سورة الجاثية (فَلِلَّهِ الْحَمْدُ رَبِّ السَّمَاوَاتِ وَرَبِّ الْأَرْضِ...)؟", os: ["رَبِّ الْعَالَمِينَ", "وهو العزيز الحكيم", "وله الكبرياء في السماوات والأرض", "وهو الغفور الرحيم"], a: 0 },
                { q: "كم آية تفصل بين بداية سورة الدخان وآية المهل ببطون أهل النار (الآية 45)؟", os: ["تفصل بينهما 44 آية متتابعة", "عشر آيات", "عشرون آية", "خمس آيات"], a: 0 },
                { q: "ما هو ختام الآية رقم 56 في سورة الدخان (لَا يَذُوقُونَ فِيهَا الْمَوْتَ إِلَّا الْمَوْتَةَ الْأُولَىٰ...)؟", os: ["وَوَقَاهُمْ عَذَابَ الْجَحِيمِ * فَضْلًا مِّن رَّبِّكَ ۚ ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ", "خالدين فيها أبداً", "لهم فيها ما يشاؤون", "إن هذا لهو الفوز العظيم"], a: 0 },
                { q: "ما هي الآية رقم 59 (آخر آية في سورة الدخان)؟", os: ["فَارْتَقِبْ إِنَّهُم مُّرْتَقِبُونَ", "فإنما يسرناه بلسانك لعلهم يتذكرون", "إن يوم الفصل ميقاتهم أجمعين", "كذلك وزوجناهم بحور عين"], a: 0 },
                { q: "ما الكلمة التي افتتحت بها الآية رقم 30 في سورة الجاثية عند تفصيل جزاء المؤمنين؟", os: ["فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِي رَحْمَتِهِ ۚ ذَٰلِكَ هُوَ الْفَوْزُ الْمُبِينُ", "وأما الذين كفروا أفلم تكن آياتي", "وقيل اليوم ننساكم", "وذلكم بأنكم اتخذتم"], a: 0 }
