                { q: "ما معنى (اعْلَمُوا أَنَّمَا الْحَيَاةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌ بَيْنَكُمْ) ب الحديد 20؟", os: ["تزهيد وتصوير لحقيقة الدنيا الفانية ب خمس مراحل: لعب ب الطفولة، لهو ب الشباب، زينة ب الفتوة، تفاخر وتكاثر ب الكبر", "تحريم الحياة بالدنيا", "أمر ب ترك العمل والتجارة", "خاص ب الكفار المشركين"], a: 0 },
                { q: "ما معنى (كَمَثَلِ غَيْثٍ أَعْجَبَ الْكُفَّارَ نَبَاتُهُ ثُمَّ يَهِيجُ فَتَرَاهُ مُصْفَرًّا)؟", os: ["مثل الدنيا ك مطر أنبت زراعاً أعجب المزارعين والزارع (الكفار)، ثم يجف ويتكسر حطاماً ب حطام فكذلك الدنيا", "مثل أعمال الكفار بالقيامة", "مثل المال والذهب ب الأسواق", "خاص بأهل مكة"], a: 0 },
                { q: "ما معنى (لِّكَيْلَا تَأْسَوْا عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا بِمَا آتَاكُمْ) ب الحديد 23؟", os: ["تربية إيمانية ب الرضا بالقدر: لئلا تحزنوا حزناً يأسأ على ما فاتكم من الدنيا، ولا تفرحوا بطراً بما آتاكم الله", "لا تحزنوا على موت الأقارب", "لا تفرحوا بالعيد والولادة", "خاص ب الأنبياء والرسل"], a: 0 },
                { q: "ما معنى (وَأَنزَلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَافِعُ لِلنَّاسِ) ب الحديد 25؟", os: ["خلق وأوجد الله مادة وسلاح الحديد القوي ل ردع الأعداء بالقتال (بأس شديد)، وفي الصنائع والعمائر (منافع للناس)", "أنزل الحديد من السماء ك المطر", "خاص ب سلاح داوود فقط", "صناعة الذهب والفضة"], a: 0 },
                { q: "ما معنى (وَلِيَعْلَمَ اللَّهُ مَن يَنصُرُهُ وَرُسُلَهُ بِالْغَيْبِ)؟", os: ["ليظهر ويكشف الله الصادقين الذين يجاهدون بسلاح الحديد نصرة لدينه ورسله ب السر والغيب", "ليعلم من يصلي بالمسجد", "ليعلم من يتصدق بالمال", "خاص ب أسرى بدر الكبرى"], a: 0 },
                { q: "ما معنى (وَجَعَلْنَا فِي ذُرِّيَّتِهِمَا النُُّبُوَّةَ وَالْكِتَابَ) ل نوح وإبراهيم؟", os: ["تكريم واصطفاء ب جعل جميع الأنبياء والكتب السماوية النازلة محصورة في نسل وعقب نوح وإبراهيم", "جعل الملك والسلطان فيهم", "خاص ب بني إسرائيل فقط", "خاص ب أمة محمد"], a: 0 },
                { q: "ما معنى (وَرَهْبَانِيَّةً ابْتَدَعُوهَا مَا كَتَبْنَاهَا عَلَيْهِمْ) ب سورة الحديد 27؟", os: ["الغلو والانقطاع ب الصوامع والزهد الذي اخترعه أتباع عيسى من عند أنفسهم بغير أمر إلهي فما رعوها حق رعايتها", "الرهبانية ب إقامة الصلاة", "الزهد ب المال والحلال", "خاص ب أحبار اليهود"], a: 0 },
                { q: "ما معنى (يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِ) ب الحديد 28؟", os: ["يعطكم ويمنحكم أجرين ونصيبين مضاعفين من الرحمة والنعيم (لإيمانكم بعيسى ثم بمحمد)", "يعطكم ضعف المال والولد", "يعطكم ملك الدنيا والآخرة", "خاص ب الصحابة ب بدر"], a: 0 },
                { q: "ما معنى (وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِ) ب الحديد 28؟", os: ["يجعل لكم هدى وبصيرة ب القلوب، ونوراً ساطعاً ب الصراط يوم القيامة تمشون به في الظلمات", "نور الشمس ب النهار", "نور القناديل ب المساجد", "خاص ب الأنبياء والرسل"], a: 0 }
